import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2026Q2 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2026Q2 Ceph社区季度进展报告","date":"2026-06-01T00:00:00.000Z","updated":"2026-06-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/2026Q2_Ceph社区季度总结.md","filePath":"posts/2026/2026Q2_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2026/2026Q2_Ceph社区季度总结.md"};function h(l,e,_,n,s,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>已收到所有材料，直接基于提供的内容生成报告。</p><hr><h1 id="ceph-2026q2-社区季度进展报告" tabindex="-1">Ceph 2026Q2 社区季度进展报告 <a class="header-anchor" href="#ceph-2026q2-社区季度进展报告" aria-label="Permalink to &quot;Ceph 2026Q2 社区季度进展报告&quot;">​</a></h1><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><p>本季度社区讨论高度集中在以下几个反复出现的技术方向：</p><h3 id="_1-fast-ec-快速纠删码-性能优化" tabindex="-1">1. Fast EC（快速纠删码）性能优化 <a class="header-anchor" href="#_1-fast-ec-快速纠删码-性能优化" aria-label="Permalink to &quot;1. Fast EC（快速纠删码）性能优化&quot;">​</a></h3><p>Fast EC 是本季度最受关注的技术议题，贯穿多场会议与演讲。<a href="/VideoSummary/posts/2026/FastEC_in_Ceph_Tentacle_A_Technical_Deep_Dive_into_Next_Gen_Erasure_Coding_Performance.html">FastEC_in_Ceph_Tentacle_A_Technical_Deep_Dive_into_Next_Gen_Erasure_Coding_Performance</a>) 对Tentacle 版本中 partial reads、partial writes、arity delta writes 等核心优化进行了深度解析。<a href="/VideoSummary/posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.html">Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC</a>) 则通过 IBM 团队的实测数据，揭示了 Fast EC 中存在的内存泄漏问题并完成修复，修复后 IOPS 提升约 33%。</p><h3 id="_2-rgw-重构与功能完善" tabindex="-1">2. RGW 重构与功能完善 <a class="header-anchor" href="#_2-rgw-重构与功能完善" aria-label="Permalink to &quot;2. RGW 重构与功能完善&quot;">​</a></h3><p>RGW Refactoring Meeting 本季度共召开 10 余次，覆盖 lifecycle policy、multipart upload 安全性、小对象存储效率、cloud transition、加密（GCM/SSE）、OIDC、list 请求限速等多个方向，是本季度讨论最密集的子系统。</p><h3 id="_3-小对象存储效率" tabindex="-1">3. 小对象存储效率 <a class="header-anchor" href="#_3-小对象存储效率" aria-label="Permalink to &quot;3. 小对象存储效率&quot;">​</a></h3><p>多个会议从不同角度讨论了小对象在 erasure coding 场景下的低效问题，包括 object packing、write coalescing、内联存储（inline xattr）等方案，尚处于设计探讨阶段。</p><h3 id="_4-umbrella-版本升级测试稳定性" tabindex="-1">4. Umbrella 版本升级测试稳定性 <a class="header-anchor" href="#_4-umbrella-版本升级测试稳定性" aria-label="Permalink to &quot;4. Umbrella 版本升级测试稳定性&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.html">Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026</a>) 专门讨论了 Umbrella 升级测试大量失败的问题，主要原因是 health warning 触发测试框架误判，而非升级流程本身存在根本性问题。</p><h3 id="_5-cephfs-新特性交付" tabindex="-1">5. CephFS 新特性交付 <a class="header-anchor" href="#_5-cephfs-新特性交付" aria-label="Permalink to &quot;5. CephFS 新特性交付&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/CephFS_News.html">CephFS_News</a>) 系统梳理了 Tentacle 已交付特性和 Umbrella 规划特性，涵盖 sub volume metrics、用户空间加密、MDS QoS、mirror daemon 增强等多个方向。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="fast-ec-内存泄漏修复与性能验证" tabindex="-1">Fast EC 内存泄漏修复与性能验证 <a class="header-anchor" href="#fast-ec-内存泄漏修复与性能验证" aria-label="Permalink to &quot;Fast EC 内存泄漏修复与性能验证&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.html">Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC</a>) 记录了一个关键发现：Fast EC 在 PG 进入 idle 状态时，EC dummy ops 创建的约 1KB 对象未被正确释放，导致内存持续泄漏，OSD 实际内存消耗远低于 target（16GB target 实际仅 1GB）。修复后：</p><ul><li>CPU 使用率从约 780% 降至 600%</li><li>16K block size 下 IOPS 从约 1.2M 提升至 1.6M</li><li>12 节点集群验证了线性扩展能力</li></ul><h3 id="rgw-小对象内联存储方案" tabindex="-1">RGW 小对象内联存储方案 <a class="header-anchor" href="#rgw-小对象内联存储方案" aria-label="Permalink to &quot;RGW 小对象内联存储方案&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-11.html">Ceph_RGW_Refactoring_Meeting_2026-03-11</a>) 提出将小于 320~512 字节的对象数据直接存储在 xattr（BlueStore RocksDB Omap）中，省去 manifest，实现零额外 block 开销。在 erasure coding 4+2 场景下，一个 256 字节对象当前消耗约 24KB 存储空间，该方案可将其降至字节级别。</p><h3 id="rgw-lifecycle性能优化" tabindex="-1">RGW Lifecycle性能优化 <a class="header-anchor" href="#rgw-lifecycle性能优化" aria-label="Permalink to &quot;RGW Lifecycle性能优化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-04-29.html">Ceph_RGW_Refactoring_Meeting_2026-04-29</a>) 和 <a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.html">Ceph_RGW_Refactoring_Meeting_2026-05-06</a>) 讨论了两个方向：</p><ul><li><strong>版本对象批量删除</strong>：将相同 key 下多版本对象归组，使用 multi-delete 批量处理，实测版本化 bucket lifecycle 处理速度提升 50%~60%</li><li><strong>多线程处理</strong>：提出 intra-RGW（单 daemon 内部 fan-out）和 cross-RGW（跨 daemon 协同）两种方案，前者 PoC 已验证 2~3 倍提升</li></ul><h3 id="cephfs-用户空间加密" tabindex="-1">CephFS 用户空间加密 <a class="header-anchor" href="#cephfs-用户空间加密" aria-label="Permalink to &quot;CephFS 用户空间加密&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/CephFS_News.html">CephFS_News</a>) 介绍了 Umbrella 版本将内核客户端加密（Linux 6.6+）移植至用户空间客户端，支持目录项名称加密和文件数据加密，无密钥者只能看到密文。</p><h3 id="cephfs-sub-volume-quarantine-隔离" tabindex="-1">CephFS Sub Volume Quarantine（隔离） <a class="header-anchor" href="#cephfs-sub-volume-quarantine-隔离" aria-label="Permalink to &quot;CephFS Sub Volume Quarantine（隔离）&quot;">​</a></h3><p>作为安全特性引入，主要应对勒索软件攻击场景。通过 manager volumes 接口对指定 sub volume 执行隔离：已挂载客户端被驱逐，新挂载请求被拒绝。</p><h3 id="s3-vector-search-近邻搜索" tabindex="-1">S3 Vector Search（近邻搜索） <a class="header-anchor" href="#s3-vector-search-近邻搜索" aria-label="Permalink to &quot;S3 Vector Search（近邻搜索）&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.html">Closer_than_you_think_-_Ceph_sjourney_to_nearest_neighbor_search</a>) 介绍了 Ceph RGW 兼容 Amazon S3 Vectors API 的工作进展，选用 LanceDB（Rust 实现，IVFPQ 索引）作为向量库，目标是在 Ceph 集群中原生支持 vector embedding存储与近邻检索，无需额外部署 PGVector、Milvus 等独立系统。</p><h3 id="bxc-rbd-懒加载镜像架构" tabindex="-1">BXC：RBD 懒加载镜像架构 <a class="header-anchor" href="#bxc-rbd-懒加载镜像架构" aria-label="Permalink to &quot;BXC：RBD 懒加载镜像架构&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports.html">BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports</a>) 介绍了 Digital Ocean 基于 RBD import-only live migration 特性设计的 Block Exchange 架构，实现 VM 启动盘的即时启动（instant boot）——OS 按需拉取 block，后台异步完成完整镜像写入，同时通过 edge cache 实现 deduplication。</p><h3 id="pg-autoscaler-均匀分配改进" tabindex="-1">PG Autoscaler 均匀分配改进 <a class="header-anchor" href="#pg-autoscaler-均匀分配改进" aria-label="Permalink to &quot;PG Autoscaler 均匀分配改进&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_User_+_Dev_Monthly_-_April_2026.html">Ceph_User_+<em>Dev_Monthly</em>-_April_2026</a>) 介绍了将 autoscaler 分配问题建模为背包问题（Knapsack Problem）的动态规划优化，修复了多个 pool 设置相同 <code>target_sizeratio</code> 时分配不均的 bug，时间复杂度 O(n log m)，升级后自动生效。</p><h3 id="_3az-stretch-cluster-的-net-split-处理" tabindex="-1">3AZ Stretch Cluster 的 Net Split 处理 <a class="header-anchor" href="#_3az-stretch-cluster-的-net-split-处理" aria-label="Permalink to &quot;3AZ Stretch Cluster 的 Net Split 处理&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster.html">Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster</a>) 提出了 Detect → Decide → Fence 三步方案：使用 Bron-Kerbosch 最大团算法选出胜出分区，支持用户配置 zone preference 或自动启发式决策，并通过 fencing 机制隔离落败分区，防止 split-brain。</p><h3 id="dashboard-性能大幅提升" tabindex="-1">Dashboard 性能大幅提升 <a class="header-anchor" href="#dashboard-性能大幅提升" aria-label="Permalink to &quot;Dashboard 性能大幅提升&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Dashboard_Roadmap.html">Ceph_Dashboard_Roadmap</a>) 报告了 Tentacle 版本 dashboard 的重要里程碑：LCP（Largest Contentful Paint）从 9.82 秒降至 2.11 秒，达到 2.5 秒以内的性能基准。</p><h3 id="rgw-lua-动态数据放置" tabindex="-1">RGW Lua 动态数据放置 <a class="header-anchor" href="#rgw-lua-动态数据放置" aria-label="Permalink to &quot;RGW Lua 动态数据放置&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_S3_Dynamic_Placement_and_Optimized_Retention.html">Ceph_S3_Dynamic_Placement_and_Optimized_Retention</a>) 展示了通过 Lua 脚本在 pre-request 阶段动态分配 storage class 的实践，延迟开销在微秒级别，支持按对象大小、扩展名、bucket 名等维度路由，实现小对象走 replicated pool、大对象走 erasure coding pool 的自动分层。</p><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><h3 id="tentacle-版本发布" tabindex="-1">Tentacle 版本发布 <a class="header-anchor" href="#tentacle-版本发布" aria-label="Permalink to &quot;Tentacle 版本发布&quot;">​</a></h3><p>本季度 Tentacle（Ceph 30.x）已正式发布，多个会议以 Tentacle 为基准讨论新特性和 backport 工作。<a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-25.html">Ceph_RGW_Refactoring_Meeting_2026-02-25</a>) 提到 lifecycle policy 删除 bug 的 backport 已合并至 Squid 分支，将随 19.2.4 发布。</p><h3 id="umbrella-版本-feature-freeze" tabindex="-1">Umbrella 版本 Feature Freeze <a class="header-anchor" href="#umbrella-版本-feature-freeze" aria-label="Permalink to &quot;Umbrella 版本 Feature Freeze&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.html">Ceph_RGW_Refactoring_Meeting_2026-05-06</a>) 明确宣布 Umbrella 版本的 feature freeze 将于 2026 年 5 月底到来，有意合入新功能的开发者需在月底前完成相关工作。</p><h3 id="umbrella-升级-kickoff-pr-合并" tabindex="-1">Umbrella 升级 Kickoff PR 合并 <a class="header-anchor" href="#umbrella-升级-kickoff-pr-合并" aria-label="Permalink to &quot;Umbrella 升级 Kickoff PR 合并&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.html">Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026</a>) 记录了 Umbrella 升级 kickoff PR 已合并，尽管升级测试存在大量失败，团队决定先合并再跟进修复，并建立 baseline 调度机制。</p><h3 id="mds-qos-tech-preview" tabindex="-1">MDS QoS Tech Preview <a class="header-anchor" href="#mds-qos-tech-preview" aria-label="Permalink to &quot;MDS QoS Tech Preview&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/CephFS_News.html">CephFS_News</a>) 宣布基于 DM-Clock 算法的 MDS QoS 将在 Umbrella 版本以 Tech Preview 形式发布，计划在 Vampire 版本达到 GA。</p><h3 id="ceph-配置变更可追踪机制上线" tabindex="-1">Ceph 配置变更可追踪机制上线 <a class="header-anchor" href="#ceph-配置变更可追踪机制上线" aria-label="Permalink to &quot;Ceph 配置变更可追踪机制上线&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Don_t_Get_Conf_d_Making_Ceph_Configuration_Changes_Obvious.html">Don_t_Get_Conf_d_Making_Ceph_Configuration_Changes_Obvious</a>) 介绍了 CI 中新增的 <strong>ceph-config-diff</strong> 检查，在每个 PR 提交时自动检测配置项变更并提示开发者更新 release notes，相关脚本已合入上游仓库。</p><h3 id="ceph-作为-nas-平台的架构就绪声明" tabindex="-1">Ceph 作为 NAS 平台的架构就绪声明 <a class="header-anchor" href="#ceph-作为-nas-平台的架构就绪声明" aria-label="Permalink to &quot;Ceph 作为 NAS 平台的架构就绪声明&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_as_a_NAS_Platform_Are_We_Architecturally_Ready.html">Ceph_as_a_NAS_Platform_Are_We_Architecturally_Ready</a>) 系统梳理了 Ceph 从 NFS/Samba 存储后端演进为原生 NAS 平台的历程：Reef 版本引入 NFS 原生编排，Squid 版本引入 SMB 原生编排，配置统一存储于 RADOS 层，标志着 Ceph 在架构层面已具备完整 NAS 平台能力。</p><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><h3 id="大规模生产用户经验分享" tabindex="-1">大规模生产用户经验分享 <a class="header-anchor" href="#大规模生产用户经验分享" aria-label="Permalink to &quot;大规模生产用户经验分享&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/10_years_of_Ceph_at_Walmart.html">10_years_of_Ceph_at_Walmart</a>) 是本季度最具代表性的用户案例分享。沃尔玛三位工程师回顾了从 2015 年 Hammer 版本到 2025 年 Reef 版本的十年演进历程，涵盖硬件从 SATA 到 NVMe、网络从 10GbE 到 100GbE、部署从裸机到容器的全面升级，并分享了外部端到端延迟监控的重要性——Ceph dashboard 内置延迟指标在大版本升级期间显示 30 微秒，而外部监控实测最大延迟达 1~5 秒。</p><h3 id="ceph-india-社区活动" tabindex="-1">Ceph India 社区活动 <a class="header-anchor" href="#ceph-india-社区活动" aria-label="Permalink to &quot;Ceph India 社区活动&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Dashboard_Roadmap.html">Ceph_Dashboard_Roadmap</a>) 来自 Ceph India 社区活动，展示了 dashboard 团队在 Tentacle 版本的交付成果，包括 multicluster dashboard、OAuth2 SSO、SMB 管理、RGW 对象存储增强、NVMe-oF TCP 管理等。</p><h3 id="google-summer-of-code-新成员加入" tabindex="-1">Google Summer of Code 新成员加入 <a class="header-anchor" href="#google-summer-of-code-新成员加入" aria-label="Permalink to &quot;Google Summer of Code 新成员加入&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-13.html">Ceph_RGW_Refactoring_Meeting_2026-05-13</a>) 记录了 GSoC 学生 Gaut 的自我介绍，社区持续吸引新贡献者参与 RGW 相关工作，包括 TCMalloc heap profiler 等项目。</p><h3 id="ci-基础设施历史回顾" tabindex="-1">CI 基础设施历史回顾 <a class="header-anchor" href="#ci-基础设施历史回顾" aria-label="Permalink to &quot;CI 基础设施历史回顾&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_CI_and_Developer_Tooling_-_Past_Present_and_Futur.html">Ceph_CI_and_DeveloperTooling_-_Past_Present_and_Futur</a>) 由 David Galloway 系统回顾了 Ceph CI 从 2014 年 InkTank 收购至今的演进历程，包括实验室从 Irvine 到 Morisville 再到 Poughkeepsie 的迁移，以及从 GitBuilders 到 Jenkins Pipeline 的工具链升级。目前每天运行约 2,000~3,000 个集成测试任务。</p><h3 id="支持工程师与开发者之间的协作障碍" tabindex="-1">支持工程师与开发者之间的协作障碍 <a class="header-anchor" href="#支持工程师与开发者之间的协作障碍" aria-label="Permalink to &quot;支持工程师与开发者之间的协作障碍&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Barriers_between_Ceph_Development_and_Ceph_Support.html">Barriers_between_Ceph_Development_and_Ceph_Support</a>) 来自 Croyd 公司的 L2 支持工程师，详细描述了容器化部署模式下支持团队无法快速构建和分发 patch 镜像的困境，推动社区改进 <code>build_with_container.py</code> 工具链，相关 patch 正在推进 backport 至 squid 和 tentacle 分支。</p><h3 id="ai-工具辅助测试日志分析" tabindex="-1">AI 工具辅助测试日志分析 <a class="header-anchor" href="#ai-工具辅助测试日志分析" aria-label="Permalink to &quot;AI 工具辅助测试日志分析&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.html">Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026</a>) 中，开发者 Alex 分享了使用 IBM watsonx Code Assistant（基于 Claude Code）辅助分析大量测试日志的经验，在定位有效调试信息方面命中率较高，显著提升了日志分析效率。</p><h3 id="kcli-容器化开发环境推广" tabindex="-1">KCLI 容器化开发环境推广 <a class="header-anchor" href="#kcli-容器化开发环境推广" aria-label="Permalink to &quot;KCLI 容器化开发环境推广&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Containerized_deployment_of_Ceph_with_KCLI.html">Containerized_deployment_of_Ceph_with_KCLI</a>) 介绍了 Crimson 团队使用 KCLI 工具快速 provision 多OS 版本虚拟机集群的实践，支持 Classic OSD 和 Crimson OSD 两种模式，解决了裸机开发环境 OS 版本锁定、镜像 tag 难以对齐等问题，同时加速了 Rocky 10 的全面支持推进。</p><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度讨论，预计 2026Q3 将重点推进以下方向：</p><h3 id="_1-umbrella-版本发布与稳定化" tabindex="-1">1. Umbrella 版本发布与稳定化 <a class="header-anchor" href="#_1-umbrella-版本发布与稳定化" aria-label="Permalink to &quot;1. Umbrella 版本发布与稳定化&quot;">​</a></h3><p>Feature freeze 已于 5 月底到来，Q3 将进入 Umbrella 版本的QA 测试、bug 修复和发布准备阶段。升级测试 baseline 的建立和 health warning 误判问题的修复是近期优先项。</p><h3 id="_2-fast-ec-生产化推广" tabindex="-1">2. Fast EC 生产化推广 <a class="header-anchor" href="#_2-fast-ec-生产化推广" aria-label="Permalink to &quot;2. Fast EC 生产化推广&quot;">​</a></h3><p>内存泄漏修复后，Fast EC 的性能优势已得到验证。预计 Q3 将有更多用户开始评估从 Classic EC迁移，社区也将持续完善 <code>allow_ec_optimizations</code> 相关文档和最佳实践。</p><h3 id="_3-rgw-小对象存储效率落地" tabindex="-1">3. RGW 小对象存储效率落地 <a class="header-anchor" href="#_3-rgw-小对象存储效率落地" aria-label="Permalink to &quot;3. RGW 小对象存储效率落地&quot;">​</a></h3><p>小对象内联存储（xattr inline）和 object packing 方案本季度完成了设计讨论，Q3 预计进入原型实现和 PR 提交阶段，重点需要解决向后兼容性（zone feature flag保护）问题。</p><h3 id="_4-rgw-lifecycle-多线程处理" tabindex="-1">4. RGW Lifecycle 多线程处理 <a class="header-anchor" href="#_4-rgw-lifecycle-多线程处理" aria-label="Permalink to &quot;4. RGW Lifecycle 多线程处理&quot;">​</a></h3><p>intra-RGW fan-out 方案 PoC 已验证 2~3 倍提升，Q3 预计提交正式 PR。针对单桶百亿对象的极端场景，cross-RGW 协同方案的设计讨论也将继续推进。</p><h3 id="_5-cephfs-mds-qos-ga" tabindex="-1">5. CephFS MDS QoS GA <a class="header-anchor" href="#_5-cephfs-mds-qos-ga" aria-label="Permalink to &quot;5. CephFS MDS QoS GA&quot;">​</a></h3><p>MDS QoS 在 Umbrella 以 Tech Preview 发布后，社区将收集用户反馈，为 Vampire 版本的 GA 做准备。</p><h3 id="_6-3-az-stretch-cluster-正式支持" tabindex="-1">6. 3 AZ Stretch Cluster 正式支持 <a class="header-anchor" href="#_6-3-az-stretch-cluster-正式支持" aria-label="Permalink to &quot;6. 3 AZ Stretch Cluster 正式支持&quot;">​</a></h3><p>Detect → Decide → Fence 方案的实现工作预计在 Q3 继续推进，MON 连通性评分功能已在 Squid 合并，决策与 fencing 逻辑是下一步重点。</p><h3 id="_7-s3-vector-search-功能完善" tabindex="-1">7. S3 Vector Search 功能完善 <a class="header-anchor" href="#_7-s3-vector-search-功能完善" aria-label="Permalink to &quot;7. S3 Vector Search 功能完善&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.html">Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search</a>) 中的 LanceDB 集成工作预计在 Q3 进入更成熟的实现阶段，目标是达到 sub-millisecond 查询延迟。</p><h3 id="_8-rgw-加密体系完善" tabindex="-1">8. RGW 加密体系完善 <a class="header-anchor" href="#_8-rgw-加密体系完善" aria-label="Permalink to &quot;8. RGW 加密体系完善&quot;">​</a></h3><p>GCM 加密 PR 的安全审查（计划引入 Cloudflare 团队）、SSE 对象 copy 修复、lifecycle transition 中的 recompression/re-encryption 支持，预计在 Q3 陆续完成并合入。</p><h3 id="_9-ceph-ci-实验室迁移完成" tabindex="-1">9. Ceph CI 实验室迁移完成 <a class="header-anchor" href="#_9-ceph-ci-实验室迁移完成" aria-label="Permalink to &quot;9. Ceph CI 实验室迁移完成&quot;">​</a></h3><p>上游实验室迁至 Poughkeepsie 后仍有约四分之三设备处于网络接入待完成状态，Q3 预计完成基础设施恢复，升级测试的定期 baseline 调度也将随之恢复。</p><hr><p><em>本报告基于 2026Q2 共39 篇会议与视频总结材料整理，所有技术内容均来源于实际记录，未作推断性补充。</em></p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2026/10_years_of_Ceph_at_Walmart.html">10 years of Ceph at Walmart</a>)</li><li><a href="/VideoSummary/posts/2026/BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports.html">BXC - An Architecture for Lazy RBD Imaging and Snapshot Exports</a>)</li><li><a href="/VideoSummary/posts/2026/Barriers_between_Ceph_Development_and_Ceph_Support.html">Barriers between Ceph Development and Ceph Support</a>)</li><li><a href="/VideoSummary/posts/2026/CephFS_News.html">CephFS News</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_CI_and_Developer_Tooling_-_Past_Present_and_Futur.html">Ceph CI and Developer Tooling- Past, Present, and Futur</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_Dashboard_Roadmap.html">Ceph Dashboard Roadmap</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_Developer_Monthly_Meetup_EMEA_-_April_2026.html">Ceph Developer Monthly Meetup EMEA - April 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.html">Ceph EC Performance Journey- Classic vs. Fast EC</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_-_2_18_2026.html">Ceph RGW Refactoring Meeting - 2/18/2026</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-25.html">Ceph RGW Refactoring Meeting 2026-02-25</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-04.html">Ceph RGW Refactoring Meeting 2026-03-04</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-11.html">Ceph RGW Refactoring Meeting 2026-03-11</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-18.html">Ceph RGW Refactoring Meeting 2026-03-18</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-03-25.html">Ceph RGW Refactoring Meeting 2026-03-25</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-04-01.html">Ceph RGW Refactoring Meeting 2026-04-01</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-04-15.html">Ceph RGW Refactoring Meeting 2026-04-15</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-04-29.html">Ceph RGW Refactoring Meeting 2026-04-29</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-06.html">Ceph RGW Refactoring Meeting 2026-05-06</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-13.html">Ceph RGW Refactoring Meeting 2026-05-13</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_S3_Dynamic_Placement_and_Optimized_Retention.html">Ceph S3 – Dynamic Placement and Optimized Retention</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_User_+_Dev_Monthly_-_April_2026.html">Ceph User + Dev Monthly - April 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_User_+_Dev_Monthly_Meetup_-_May_2026.html">Ceph User + Dev Monthly Meetup - May 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_as_a_NAS_Platform_Are_We_Architecturally_Ready.html">Ceph as a NAS Platform Are We Architecturally Ready?</a>)</li><li><a href="/VideoSummary/posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.html">Closer than you think- Cephs journey to nearest neighbor search</a>)</li><li><a href="/VideoSummary/posts/2026/Containerized_deployment_of_Ceph_with_KCLI.html">Containerized deployment of Ceph with KCLI</a>)</li><li><a href="/VideoSummary/posts/2026/Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster.html">Detect, Decide, Fence Resolving Netsplits in 3 AZ Stretch Cluster</a>)</li><li><a href="/VideoSummary/posts/2026/Don_t_Get_Conf_d_Making_Ceph_Configuration_Changes_Obvious.html">Dont Get Confd Making Ceph Configuration Changes Obvious</a>)</li><li><a href="/VideoSummary/posts/2026/FastEC_in_Ceph_Tentacle_A_Technical_Deep_Dive_into_Next_Gen_Erasure_Coding_Performance.html">FastEC in Ceph Tentacle A Technical Deep Dive into Next Gen Erasure Coding Performance</a>)</li><li><a href="/VideoSummary/posts/2026/HPC_Triggers.html">HPC Triggers</a>)</li><li><a href="/VideoSummary/posts/2026/Implementing_Ceph_at_GMU_s_College_of_Engineering_and_Computing.html">Implementing Ceph at GMUs College of Engineering and Computing</a>)</li><li><a href="/VideoSummary/posts/2026/MAAS_as_a_Backend_-_Provisioning_Infrastructure_for_Teuthology_Suites_With_Vaibhav_Mahajan.html">MAAS as a Backend- Provisioning Infrastructure for Teuthology Suites With Vaibhav Mahajan</a>)</li><li><a href="/VideoSummary/posts/2026/Panel_Discussion.html">Panel Discussion</a>)</li><li><a href="/VideoSummary/posts/2026/QoS_Demo.html">QoS Demo</a>)</li><li><a href="/VideoSummary/posts/2026/Rook_Ceph_Disaster_Recovery.html">Rook Ceph Disaster Recovery</a>)</li><li><a href="/VideoSummary/posts/2026/Squishing_Squids_-_A_Ceph_Compression_Guide.html">Squishing Squids - A Ceph Compression Guide</a>)</li><li><a href="/VideoSummary/posts/2026/State_of_the_Cephalopod_-_India_2026.html">State of the Cephalopod - India 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Toward_One-Click_Ceph_-_Engineering_the_Future_of_Autonomous_Storage.html">Toward One-Click Ceph- Engineering the Future of Autonomous Storage</a>)</li><li><a href="/VideoSummary/posts/2026/Tracking_Data_Availability_of_a_Ceph_Cluster.html">Tracking Data Availability of a Ceph Cluster</a>)</li><li><a href="/VideoSummary/posts/2026/Why_is_my_SSD_Pool_so_Slow_Decoupling_min_size_from_Write_Acknowledgment.html">Why is my SSD Pool so Slow? Decoupling min_size from Write Acknowledgment</a>)</li></ul>',98)])])}const d=a(i,[["render",h]]);export{m as __pageData,d as default};
